import {Vector3,Quaternion} from '@babylonjs/core/Maths/math.vector.js';
import {contactEffort,contactFrameFeedback} from '../../research/stand-up-contact-effort.mjs';
export function contactPolicy({model,parameters:p}) {
 const state={phase:'retained kneel',started:null,blend:0,saturated:0,torque:[],forces:[],soleLoaded:0,footRotation:null,handError:null,handLoad:0,armBlend:0,handStart:null};const turning=[];
 const policy=o=>{
  state.started??=o.time;
  const u=Math.max(0,Math.min(1,(o.time-state.started-p.wait)/p.seconds));
  // A cubic blend starts and ends with zero target speed.
  state.blend=u*u*(3-2*u);state.phase=u===0?'retained kneel':u<1?'foot placement':'placement hold';
  const armU=Math.max(0,Math.min(1,(o.time-state.started-p.wait-(p.armDelay??0))/p.seconds));
  state.armBlend=armU*armU*(3-2*armU);
  const targets=p.targets.map((v,i)=>v+(p.armDelay&&/^(shoulder|elbow|wrist)\.left/.test(model.channels[i].name)?state.armBlend:state.blend)*(p.nextTargets[i]-v));
  const loaded=new Set(o.contacts.filter(c=>c.fixed!==null&&c.impulse>0).map(c=>c.segment));
  const forces=p.forces.filter(f=>!p.contactFilter||loaded.has(f.segment)).map(f=>p.fadeSupports?.includes(f.segment)?{...f,force:f.force.map(v=>v*(1-(f.segment==='hand.left'?state.armBlend:state.blend)))}:f);
  const total=p.forces.reduce((n,f)=>n+f.force[1],0),remaining=forces.reduce((n,f)=>n+f.force[1],0),scale=remaining>0?total/remaining:0;
  state.forces=forces.map(f=>({segment:f.segment,force:f.force.map(v=>v*scale)}));
  const patches=forces.map(f=>{const s=o.segments.find(s=>s.name===f.segment);return {kind:'point',at:new Vector3(...f.local).applyRotationQuaternionToRef(new Quaternion(...s.rotation),new Vector3()).addInPlaceFromFloats(...s.position)};});
  const e=contactEffort(model,o,patches,forces.map(f=>f.segment),targets,{poseGain:0,poseDamping:0});
  const feed=Array.from(e.t0,(v,i)=>(v-forces.reduce((sum,f,k)=>sum+f.force.reduce((n,x,j)=>n+e.C[i*6*forces.length+6*k+j]*x*scale,0),0))/e.scales[i]);
  let feedback=null;
  if(p.orientationGain){
   state.footRotation??=[...o.segments.find(s=>s.name==='foot.left').rotation];
   const sign=state.footRotation.reduce((n,v,i)=>n+v*p.footRotation[i],0)<0?-1:1;
   const mix=state.footRotation.map((v,i)=>v+state.blend*(sign*p.footRotation[i]-v)),norm=Math.sqrt(mix.reduce((n,v)=>n+v*v,0));
   feedback=contactFrameFeedback(model,o,{orientationTargets:{'foot.left':{rotation:mix.map(v=>v/norm),gain:p.orientationGain,damping:.06}}});
  }
  if(p.handGain){
   const s=o.segments.find(s=>s.name==='hand.left');
   state.handStart??=new Vector3(...p.handGoal.at).applyRotationQuaternionToRef(new Quaternion(...s.rotation),new Vector3()).addInPlaceFromFloats(...s.position).asArray();
   const target=state.handStart.map((v,i)=>v+state.armBlend*(p.handGoal.target[i]-v));
   // The hand clears the floor midway through its horizontal placement.
   target[1]+=4*p.handLift*state.armBlend*(1-state.armBlend);
   const f=contactFrameFeedback(model,o,{positionTargets:{'hand.left':{at:p.handGoal.at,target,gain:p.handGain,damping:.06}},orientationTargets:{'hand.left':{rotation:p.handRotation,gain:.5,damping:.06}}});
   feedback=feedback?feedback.map((v,i)=>v+f[i]):f;
  }
  const velocity=[],activation=[];let first=0;state.saturated=0;
  for(const joint of model.joints){
   const angles=o.joints.slice(first,first+joint.dofs.length).map(j=>j.angle);turningToRef(joint,angles,turning);
   for(let k=0;k<joint.dofs.length;k++){
    const i=first+k,c=model.channels[i],obs=o.joints[i],peak=Math.min(c.positive.peak,c.negative.peak);
    const error=turning[k].reduce((n,v,j)=>n+v*(targets[first+j]-angles[j]),0);
