   }first+=joint.dofs.length;
  }
  state.soleLoaded=o.contacts.filter(c=>c.fixed!==null&&c.segment==='foot.left').reduce((n,c)=>n+c.impulse*120,0);
  if(p.handGoal){
   const s=o.segments.find(s=>s.name==='hand.left'),at=new Vector3(...p.handGoal.at).applyRotationQuaternionToRef(new Quaternion(...s.rotation),new Vector3()).addInPlaceFromFloats(...s.position);
   state.handError=at.subtract(new Vector3(...p.handGoal.target)).length();
   state.handLoad=o.contacts.filter(c=>c.fixed!==null&&c.segment==='hand.left').reduce((n,c)=>n+c.impulse*120,0);
  }
  return {kind:'muscles',velocity,activation,handPoses:{left:'open',right:'open'}};
 };policy.state=state;return policy;
}

