import {contactPolicy as preparePolicy} from './anchored-policy.mjs';
import {turningToRef} from '../../src/core/build/joint-state.ts';
export function contactPolicy(args){
 const {model,parameters:p}=args,prepare=preparePolicy(args),state={prepare:prepare.state,started:null,riseAt:null,from:null,phase:'prepare feet'},turning=[];
 const policy=o=>{
  state.started??=o.time;
  if(o.time-state.started<p.riseAfter)return prepare(o);
  state.riseAt??=o.time;state.from??=o.joints.map((j,i)=>Math.max(model.channels[i].min,Math.min(model.channels[i].max,j.angle)));
  const u=Math.max(0,Math.min(1,(o.time-state.riseAt)/p.standSeconds)),blend=u*u*(3-2*u);
  state.phase='stand';const targets=state.from.map((v,i)=>v+blend*(model.referenceAngles[i]-v)),activation=[],velocity=[];let first=0;
  for(const joint of model.joints){
   const n=joint.dofs.length,angles=o.joints.slice(first,first+n).map(j=>j.angle);turningToRef(joint,angles,turning);
   for(let k=0;k<n;k++){const error=turning[k].reduce((s,v,j)=>s+v*(targets[first+j]-angles[j]),0);activation.push(1);velocity.push(Math.max(-8,Math.min(8,p.standGain*error)));}first+=n;
  }
  return {kind:'muscles',activation,velocity,handPoses:{left:'open',right:'open'}};
 };policy.state=state;return policy;
}

