 return {window:[a,b],samples:selected.length,first:selected[0]&&{...selected[0],joints:undefined},last:selected.at(-1)&&{...selected.at(-1),joints:undefined},joints:joints.filter(j=>j.saturated||j.nearLimit||j.maxError>1).sort((a,b)=>b.saturated-a.saturated)};
});
