import fs from 'node:fs';
import assert from 'node:assert/strict';
import {gunzipSync} from 'node:zlib';
import {deserialize} from 'node:v8';
import {createHash} from 'node:crypto';
const sources=['stand-up-rogue-guidance/baseline','stand-up-rogue-guidance/reached','stand-up-rogue-guidance/upright','stand-up-pre-transfer/loaded','stand-up-pre-transfer/released','stand-up-held-kneel/tripod'];
const results=sources.map(name=>{
 const path='.review/'+name+'.trace.gz',t=deserialize(gunzipSync(fs.readFileSync(path))),hash=createHash('sha256');
 for(const r of t.rows)hash.update(JSON.stringify(r.observation));assert.equal(hash.digest('hex'),t.traceSha256);
 const bySide=['left','right'].map((side,si)=>{
  const spans=[];let current=null;
  for(let i=0;i<t.rows.length;i++){
   const r=t.rows[i],o=r.observation,load=o.contacts.filter(c=>c.segment==='foot.'+side&&c.fixed!==null&&c.impulse>0&&-c.normal[1]>.9).reduce((n,c)=>n+c.impulse*120,0);
   const yes=r.soleUp[si]>.8&&load>20;
   if(yes){if(!current)current={first:i+1,last:i+1,from:r.result.elapsed,to:r.result.elapsed,minLoad:load,maxHeight:o.height};current.last=i+1;current.to=r.result.elapsed;current.minLoad=Math.min(current.minLoad,load);current.maxHeight=Math.max(current.maxHeight,o.height);}
   else if(current){spans.push(current);current=null;}
  }if(current)spans.push(current);
