import {Quaternion,Vector3} from '@babylonjs/core/Maths/math.vector.js';
import {motionAxesToRef,turningToRef,ratesToRef} from '../../src/core/build/joint-state.ts';
import {spinBetweenToRef} from '../../src/core/math/turn.ts';
import {contactPolicy as supportPolicy} from '../../research/stand-up-contact-policy.mjs';

function solve(A,b){
