import fs from 'node:fs';
import assert from 'node:assert/strict';
import {gunzipSync} from 'node:zlib';
import {deserialize} from 'node:v8';
import {Quaternion,Vector3} from '@babylonjs/core/Maths/math.vector.js';
import {acceptanceEnvironment} from '../../.tools/stand-up-frozen/research/stand-up-acceptance.mjs';
import {footStatesOf} from '../../src/core/control/support.ts';
import {contactModel} from '../../research/stand-up-contact-model.mjs';
import {motionAxesToRef,ratesToRef} from '../../src/core/build/joint-state.ts';
import {standUpKinematics,solveStandUpPose} from '../../research/stand-up-ik.mjs';
const dir='.review/stand-up-foot-first/',manifest=JSON.parse(fs.readFileSync('.tools/stand-up-frozen/research/stand-up-acceptance/cases.json'));
const trace=deserialize(gunzipSync(fs.readFileSync(dir+'selected.trace.gz'))),c=manifest.cases[9],e=await acceptanceEnvironment(c.configuration),prefixSteps=60;
try{
 e.restore(gunzipSync(fs.readFileSync('.tools/stand-up-frozen/research/stand-up-acceptance/'+c.file)));assert.deepEqual(e.observe(),trace.initial);
 for(let i=0;i<prefixSteps;i++)assert.deepEqual(e.step(trace.rows[i].action,{automaticHandover:true}),trace.rows[i]);
 const o=e.observe(),model=standUpKinematics({stand:e.stand,observe:e.observe,stance:{body:e.body},metadata:e.identity});

 const physical=contactModel(e),byName=new Map(o.segments.map(s=>[s.name,s])),rows=[];
 for(const name of ['foot.left','foot.right']){
  const hand=byName.get(name),f=footStatesOf(e.stand.built).find(f=>f.segment.spec.name===name),sole=f.sole.reduce((v,p)=>v.addInPlace(p),new Vector3()).scaleInPlace(1/f.sole.length),at=sole.applyRotationQuaternionToRef(new Quaternion(...hand.rotation),new Vector3()).addInPlaceFromFloats(...hand.position);
  const local=at.subtract(new Vector3(...hand.position)).applyRotationQuaternionToRef(Quaternion.Inverse(new Quaternion(...hand.rotation)),new Vector3()).asArray();
  let offset=0;
  for(const joint of physical.joints){
   const n=joint.dofs.length,angles=o.joints.slice(offset,offset+n).map(j=>j.angle);
   if(joint.descendants.includes(name)){
    const parent=byName.get(joint.parent),rotation=new Quaternion(...parent.rotation).multiply(new Quaternion(...joint.parentRestInverse));
    const pivot=new Vector3(...joint.pivot).applyRotationQuaternionToRef(new Quaternion(...parent.rotation),new Vector3()).addInPlaceFromFloats(...parent.position),arm=at.subtract(pivot);
    const axes=motionAxesToRef(joint,angles,[]);
    for(let k=0;k<n;k++){
     const axis=new Vector3(...axes[k]).applyRotationQuaternionToRef(rotation,new Vector3()),analytic=Vector3.Cross(axis,arm).asArray();
     const speeds=Array.from({length:n},(_,j)=>j===k?1:0),rates=ratesToRef(joint,angles,speeds,[]),plus=[...model.initial],minus=[...model.initial],h=1e-5;
     rates.forEach((v,j)=>{plus[6+offset+j]+=h*v;minus[6+offset+j]-=h*v;});
     const a=model.point(model.poses(plus),name,local),b=model.point(model.poses(minus),name,local),numeric=a.map((v,j)=>(v-b[j])/(2*h));
     rows.push({name,channel:physical.channels[offset+k].name,analytic,numeric,error:Math.hypot(...analytic.map((v,j)=>v-numeric[j]))});
    }
   }offset+=n;
  }
 }
 const result={identity:e.identity,prefixSteps,sourcePhysicalTraceSha256:trace.traceSha256,fkError:model.fkError,rows,maxError:Math.max(...rows.map(r=>r.error))};
 fs.writeFileSync(dir+'foot-jacobian.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({fk:result.fkError,maxError:result.maxError,rows}));
}finally{e.dispose();}
